<!-- FLOATING INTERACTIVE TOAST NOTIFICATION -->
<div class="fixed bottom-6 right-6 z-50 bg-inverse-surface text-inverse-on-surface px-4 py-3 rounded-xl shadow-2xl font-label-md text-label-md flex items-center gap-2 transform translate-y-24 transition-transform duration-300" id="adminToast">
<span class="material-symbols-outlined text-[20px] text-tertiary-fixed">info</span>
<span id="adminToastMsg" class="">Operation completed successfully.</span>
</div>
<script>
    // Global Filter State
    let currentStatus = 'ALL';

    function setStatusFilter(status, element) {
      currentStatus = status;
      document.querySelectorAll('.status-tab').forEach(tab => {
        tab.classList.remove('bg-primary', 'text-on-primary', 'font-semibold', 'shadow-sm');
        tab.classList.add('bg-surface-container', 'text-on-surface-variant');
      });
      element.classList.remove('bg-surface-container', 'text-on-surface-variant');
      element.classList.add('bg-primary', 'text-on-primary', 'font-semibold', 'shadow-sm');
      filterTableRows();
    }

    function filterTableRows() {
      const query = (document.getElementById('searchInput').value || '').toLowerCase().trim();
      const planValue = document.getElementById('planFilter').value;
      const rows = document.querySelectorAll('.tenant-row');

      rows.forEach(row => {
        const rowStatus = row.getAttribute('data-status');
        const rowPlan = row.getAttribute('data-plan');
        const rowText = row.getAttribute('data-query');

        const matchesStatus = (currentStatus === 'ALL') || (rowStatus === currentStatus);
        const matchesPlan = (planValue === 'ALL') || (rowPlan === planValue);
        const matchesQuery = !query || rowText.includes(query);

        if (matchesStatus && matchesPlan && matchesQuery) {
          row.style.display = '';
        } else {
          row.style.display = 'none';
        }
      });
    }

    function resetFilters() {
      document.getElementById('searchInput').value = '';
      document.getElementById('planFilter').value = 'ALL';
      const allBtn = document.querySelector('.status-tab');
      if (allBtn) setStatusFilter('ALL', allBtn);
      filterTableRows();
      triggerToast('Filters reset to default view.');
    }

    // Slide-over Drawer
    function openDrawer() {
      const overlay = document.getElementById('drawerOverlay');
      const panel = document.getElementById('drawerPanel');
      overlay.classList.remove('opacity-0', 'pointer-events-none');
      panel.classList.remove('translate-x-full');
    }

    function closeDrawer() {
      const overlay = document.getElementById('drawerOverlay');
      const panel = document.getElementById('drawerPanel');
      overlay.classList.add('opacity-0', 'pointer-events-none');
      panel.classList.add('translate-x-full');
    }

    // More Options Dropdown Toggle
    function toggleDropdown(btn) {
      const menu = btn.nextElementSibling;
      const allMenus = document.querySelectorAll('.action-menu');
      allMenus.forEach(m => {
        if (m !== menu) m.classList.add('hidden');
      });
      menu.classList.toggle('hidden');
    }

    // Close Dropdowns on Click Outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.relative')) {
        document.querySelectorAll('.action-menu').forEach(m => m.classList.add('hidden'));
      }
    });

    // Destructive Confirmation Modal
    let pendingAction = '';
    function openDestructiveConfirm(actionName, targetName, targetId) {
      pendingAction = actionName;
      document.getElementById('confirmActionTitle').innerText = actionName;
      document.getElementById('confirmTargetTenant').innerText = targetName;
      document.getElementById('confirmTargetId').innerText = targetId;
      document.getElementById('confirmWarningText').innerText = `Caution: Authorizing '${actionName}' modifies production DB states and issues audit telemetry for tenant ${targetId}.`;
      document.getElementById('confirmInputText').value = '';
      document.getElementById('confirmExecuteBtn').disabled = true;

      const modal = document.getElementById('confirmModal');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function closeDestructiveConfirm() {
      const modal = document.getElementById('confirmModal');
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }

    function validateConfirmationInput() {
      const val = document.getElementById('confirmInputText').value.trim();
      const btn = document.getElementById('confirmExecuteBtn');
      btn.disabled = (val !== 'CONFIRM-ACTION');
    }

    function executeDestructiveAction() {
      closeDestructiveConfirm();
      closeDrawer();
      triggerToast(`Operation '${pendingAction}' successfully propagated.`);
    }

    // Provisioning Modal
    function toggleProvisionModal(show) {
      const modal = document.getElementById('provisionModal');
      if (show) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
      } else {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
      }
    }

    function completeProvisioning() {
      toggleProvisionModal(false);
      triggerToast('Enterprise Tenant instance initialized and KMS key generated.');
    }

    // Toast helper
    let toastTimeout;
    function triggerToast(message) {
      const toast = document.getElementById('adminToast');
      const msg = document.getElementById('adminToastMsg');
      msg.innerText = message;
      toast.classList.remove('translate-y-24');
      clearTimeout(toastTimeout);
      toastTimeout = setTimeout(() => {
        toast.classList.add('translate-y-24');
      }, 3500);
    }
  </script>
</div></main></div>

